/**
 * The file-reader entity's sub-type table. Five platform resource types share
 * one ownership shape (app-scoped, own-file, one `.ts` per instance):
 * `elementum_excel_file_reader`, `elementum_json_file_reader`,
 * `elementum_text_file_reader`, `elementum_xml_file_reader`, and
 * `elementum_ai_file_reader` — exactly the `entities/field/types.ts` /
 * `entities/agent-tool/types.ts` pattern, one ROW per sub-type.
 *
 * All five variants are implemented. excel/json/text are the three
 * `elementum_file_reader_task.file_reader_id` accepts (the provider's own
 * schema docs say so explicitly); `ai` backs `elementum_ai_file_read_task`
 * instead (see `entities/automation/types.ts`'s `aiFileAnalysis` row) — a
 * live capture also confirms a plain `elementum_file_reader_task` can
 * reference one. XML shares JSON's recursive structure dialect under the
 * provider's `values` attribute.
 */
export const FILE_READER_SUB_TYPES = [
    { typeKey: "excel", resourceType: "elementum_excel_file_reader", implemented: true },
    { typeKey: "json", resourceType: "elementum_json_file_reader", implemented: true },
    { typeKey: "text", resourceType: "elementum_text_file_reader", implemented: true },
    { typeKey: "xml", resourceType: "elementum_xml_file_reader", implemented: true },
    { typeKey: "ai", resourceType: "elementum_ai_file_reader", implemented: true },
];
export const FILE_READER_SUB_TYPE_BY_TYPE_KEY = new Map(FILE_READER_SUB_TYPES.map((t) => [t.typeKey, t]));
export const FILE_READER_SUB_TYPE_BY_RESOURCE = new Map(FILE_READER_SUB_TYPES.map((t) => [t.resourceType, t]));
/** The resource types the terraform path round-trips today (adoption scope). */
export const IMPLEMENTED_FILE_READER_RESOURCE_TYPES = FILE_READER_SUB_TYPES.filter((t) => t.implemented === true).map((t) => t.resourceType);
/** Every declared file-reader resource type — stream partition recognizes these by name. */
export const ALL_FILE_READER_RESOURCE_TYPES = FILE_READER_SUB_TYPES.map((t) => t.resourceType);
